// DimDepartment — generated by src/powerbi/build_assets.py from DimDepartment.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "DimDepartment.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"department_id", type text},
        {"department_name", type text},
        {"department_manager", type text},
        {"department_location", type text},
        {"operational_budget", type number}
    }, "en-US")
in
    Typed
